import './index.less'
import { getOldInviteNewConfig, getOldReferInfo, createReferLink, sendInviteEmail, getOldInviteNewRank, getOldInviteNewEmailRank, } from "@utils/api.js"
import { copyString, SeamlessScrolling, } from "@utils/index.js"


if (!customElements.get('jky-old-invite-new-rank')) {
  customElements.define('jky-old-invite-new-rank', class extends HTMLElement {
    constructor() {
      super()

      // 配置数据
      this.configData = Object.create(null)
      this.olderEmail = '' // 老客邮箱，初始值为空

      // DOM
      this.formDOM = this.querySelector('[data-old-invite-new-form]')
      this.shareDOM = this.querySelector('[data-old-invite-new-share]')

      this.rankHeader = this.querySelector('[data-rank-header]')
      this.rankSelfData = this.querySelector('[data-rank-self-data]')
      this.rankUl = this.querySelector('[data-rank-ul]')

      this.rulesButton = this.querySelector('[data-rules-button]')
      this.rulesDOM = this.querySelector('[data-old-invite-new-rules]')

      this.rankHeaderParamsArray = this.rankHeader.dataset.rankHeaderParams.split(',').slice(0, 3).map(item => item.trim())

      // 注册规则按钮事件
      if (this.rulesButton) {
        this.rulesButton.addEventListener('click', () => {
          const popupHtml = this.rulesDOM.innerHTML
          ZModle?.getInstance(popupHtml, {
            id: `old-invite-new-rank-rules-popup`,
            class: "old-invite-new-rank-rules-popup-wrap",
            cb: () => {}
          })
        })
      }
    }
    connectedCallback() {
      if (!this._initialized) {
        this._initialized = true
        
        this.init()

        // 初始化排行榜
        this.initRank()
      }
    }
    async init() {
      try {
        const { data } = await getOldInviteNewConfig()

        if (data) {
          this.configData = data

          // 已登录
          if (window?.pageInfo?.customerInfo?.id) {
            // 赋值 老客邮箱
            this.olderEmail = window.pageInfo.customerInfo.email

            // 获取老客邀请链接
            const infoData = await getOldReferInfo({ email: this.olderEmail, })

            // 如果 有 邀请链接
            if (infoData?.data?.referLink) {
              this.renderShareDOM(infoData.data.referLink)
              // 获取邮箱排行榜
              await this.getEmailRank(this.olderEmail)
            }
            // 无邀请链接
            else {
              this.formDOM.classList.remove('!hidden')

              // 自动填入用户 email
              this.formDOM.querySelector('input').value = this.olderEmail

              this.registerFormButton(this.configData.loginButtonDesc, infoData?.data?.subscribeStatus)

              // 如果未订阅
              if (!infoData?.data?.subscribeStatus) {
                const labelDOM = this.formDOM.querySelector('label')
                this.renderPolicyDOM(labelDOM)
              }
            }
          }
          // 未登录
          else {
            this.formDOM.classList.remove('!hidden')

            this.registerFormButton(this.dataset.emailInputButtonText || this.configData.notLoginButtonDesc, false)
          }
        } else {
          // 无数据，隐藏标题
          this.querySelector('[data-get-your-link-title]').classList.add('!hidden')
        }
      } catch (err) {
        // 无数据，隐藏标题
        this.querySelector('[data-get-your-link-title]').classList.add('!hidden')
      }
    }
    // 注册 表单按钮
    registerFormButton(buttonText, subscribeStatus) {
      const inputDOM = this.formDOM.querySelector('[data-old-invite-new-form-input]')
      const buttonDOM = this.formDOM.querySelector('[data-old-invite-new-form-button]')
      const labelDOM = this.formDOM.querySelector('label')
      const emailErrorTip = this.formDOM.querySelector('[data-email-error-tip]')
      const policyErrorTip = this.formDOM.querySelector('[data-policy-error-tip]')

      const { emailEmptyErrorText, emailFormatErrorText, } = this.dataset

      buttonDOM.innerText = buttonText

      // input change
      inputDOM.addEventListener('input', (e) => emailErrorTip.classList.add('hidden'))
      labelDOM.querySelector('input[type="checkbox"]').addEventListener('change', (e) => policyErrorTip.classList.add('hidden'))

      this.formDOM.addEventListener('submit', async (e) => {
        e.preventDefault()

        buttonDOM.classList.add('btn--loading')
        this.olderEmail = inputDOM.value
        if (!this.olderEmail.trim()) {
          emailErrorTip.innerText = emailEmptyErrorText
          emailErrorTip.classList.remove('hidden')

          buttonDOM.classList.remove('btn--loading')
          return false
        }
        if (!/^\w+([-+.]\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*$/.test(this.olderEmail)) {
          emailErrorTip.innerText = emailFormatErrorText
          emailErrorTip.classList.remove('hidden')
          
          buttonDOM.classList.remove('btn--loading')
          return false
        }

        // 已订阅
        if (subscribeStatus) {
          // 生成 邀请链接
          await this.handleCreateReferLink(this.olderEmail)

          // 获取邮箱排行榜
          await this.getEmailRank(this.olderEmail)

          buttonDOM.classList.remove('btn--loading')
        } else {
          // 如果 checkbox 未显示
          if (labelDOM.classList.contains('!hidden')) {
            // 获取老客邀请链接
            const infoData = await getOldReferInfo({ email: this.olderEmail, })

            // 如果 有 邀请链接
            if (infoData.data.referLink) {
              buttonDOM.classList.remove('btn--loading')

              this.renderShareDOM(infoData.data.referLink)

              // 获取邮箱排行榜
              await this.getEmailRank(this.olderEmail)
            }
            // 无邀请链接
            else {
              // 如果未订阅
              if (!infoData?.data?.subscribeStatus) {
                this.renderPolicyDOM(labelDOM)

                buttonDOM.classList.remove('btn--loading')
              }
              // 如果已订阅
              else {
                // 生成 邀请链接
                await this.handleCreateReferLink(this.olderEmail)

                // 获取邮箱排行榜
                await this.getEmailRank(this.olderEmail)

                buttonDOM.classList.remove('btn--loading')
              }
            }
          }
          // 如果 checkbox 已显示，或者已订阅
          else {
            const isChecked = labelDOM.querySelector('#old-invite-new-agree-checkbox').checked
            if (!isChecked) {
              policyErrorTip.innerText = labelDOM.dataset.policyErrorText
              policyErrorTip.classList.remove('hidden')

              buttonDOM.classList.remove('btn--loading')
              return false
            }

            // 生成 邀请链接
            await this.handleCreateReferLink(this.olderEmail)

            // 获取邮箱排行榜
            await this.getEmailRank(this.olderEmail)
            
            buttonDOM.classList.remove('btn--loading')
          }
        }
      })
    }
    // 生成 邀请链接
    async handleCreateReferLink(email) {
      const tags = [this.dataset.userTag,'ReferOld','ReferOld-PHB-Subscribe'].filter(Boolean).join(',');
      const createData = await createReferLink({ email, customizeTag:tags,pageSource:'rank'})
      if (createData.data) {
        this.renderShareDOM(createData.data)
      }
    }
    // 渲染政策 DOM
    renderPolicyDOM(labelDOM) {
      labelDOM.classList.remove('!hidden')

      const spanDOM = labelDOM.querySelector('span')
      const { terms_service, terms_service_url, privacy_policy, privacy_policy_url, } = spanDOM.dataset
      let spanHTML = spanDOM.innerHTML

      const termsServiceHtml = `<a href="${terms_service_url}" target="_blank" class="text-#666 hover:text-primary underline underline-offset-4">${terms_service}</a>`
      const privacyPolicyHtml = `<a href="${privacy_policy_url}" target="_blank" class="text-#666 hover:text-primary underline underline-offset-4">${privacy_policy}</a>`

      spanHTML = spanHTML.replace('{termsService}', termsServiceHtml)
      spanHTML = spanHTML.replace('{PrivacyPolicy}', privacyPolicyHtml)
      spanDOM.innerHTML = spanHTML
    }
    // 渲染 分享DOM
    renderShareDOM(shareLink) {
      this.shareDOM.classList.remove('!hidden')
      this.formDOM.classList.add('!hidden')

      // 显示分享链接
      this.shareDOM.querySelector('[data-old-invite-new-share-link]').innerText = shareLink
      this.shareDOM.querySelector('[data-old-invite-new-media-desc]').innerText = this.configData.generatedMediaDesc

      // 渲染 社媒分享 icon
      this.renderShareMediaIcons(shareLink)

      // 注册 copy 事件
      this.shareDOM.querySelector('[data-old-invite-new-copy]').onclick = (e) => {
        e.target.setAttribute('disabled', 'disabled')

        const { copyText, copiedText, copySuccessTip, } = e.target.dataset
        copyString(shareLink, () => {
          // 提示 copy 成功
          pushSuccessMessage(copySuccessTip)
          e.target.innerText = copiedText

          setTimeout(() => {
            e.target.innerText = copyText
            e.target.removeAttribute('disabled')
          }, 3000)
        })
      }
    }
    // 渲染社媒Icons
    renderShareMediaIcons(shareLink) {
      const shareMediaWrap = this.querySelector('[data-old-invite-new-share-icons]')
      shareMediaWrap.querySelectorAll('[data-type]').forEach(item => {
        const type = item.dataset.type
        const medias = this.configData.medias.map(({ media, }) => media)
        if (medias.includes(type)) {
          item.classList.remove('!hidden')

          item.onclick = () => {
            if (type === 'email') {
              this.handleEmailClick(shareMediaWrap.dataset.emailPlaceholder)
            } else {
              const content = this.configData.medias.find(({ media, }) => media === type)?.mediaDesc
              const shareUrl = this.getSocialShareAPI(shareLink, type, content)
              // instagram
              if (type === 'instagram') {
                copyString(shareLink, () => {
                  // 提示 copy 成功
                  pushSuccessMessage(shareMediaWrap.dataset.instagramCopySuccessTip)
          
                  setTimeout(() => {
                    window.open('https://www.instagram.com/', '_blank')
                  }, 3000)
                })
              }
              // whatsapp 不支持小窗打开
              else if (type === 'whatsapp') {
                window.open(shareUrl, '_blank')
              }
              // 小窗打开
              else {
                let popWidth = 600,
                    popHeight = 480,
                    left = window.innerWidth / 2 - popWidth / 2 + window.screenX,
                    top = window.innerHeight / 2 - popHeight / 2 + window.screenY,
                    popParams = `scrollbars=no, width=${popWidth}, height=${popHeight}, top=${top}, left=${left}`,
                    newWindow = window.open(shareUrl, '', popParams)

                if (window.focus) {
                  newWindow.focus()
                }
              }
            }
          }
        }
      })
    }
    // 邮箱弹窗内容
    renderEmailPopup(emailPlaceholder) {
      return `
        <h2 class="w-full font-semibold text-center text-#1A1A1A text-40 leading-48 lg:j-text-32 lg:j-leading-44 xl:a-text-32 xl:a-leading-44">
          ${this.configData.emailTitle}
        </h2>
        <form class="w-full flex bg-white border-solid border-#DEDEDE mt-32 h-80 rounded-6 border-1 lg:j-h-48 lg:j-rounded-24 lg:j-border-1 lg:j-mt-25 xl:a-h-48 xl:a-rounded-24 xl:a-border-1 xl:a-mt-25">
          <input class="appearance-none flex-1 w-full h-full font-medium rounded-6 px-20 text-center text-28 lg:text-left lg:h-full lg:j-px-20 lg:j-rounded-24 lg:j-text-16 xl:a-px-20 xl:a-rounded-24 xl:a-text-16" placeholder="${emailPlaceholder}" type="text">
          <button type="submit" class="hidden lg:flex flex-center old-invite-new-button old-invite-new-highlight-button appearance-none h-full lg:j-min-w-120 lg:j-rounded-24 lg:j-text-16 xl:a-min-w-120 xl:a-rounded-24 xl:a-text-16">
            <span class="line-clamp-1">${this.configData.emailButtonDesc}</span>
          </button>
        </form>

        <p class="hidden w-full text-#FE3B30 font-normal text-28 leading-32 mt-12 lg:j-mt-8 lg:j-text-14 lg:j-leading-24 xl:a-mt-8 xl:a-text-14 xl:a-leading-24" data-email-popup-error-tip></p>

        <div class="w-full text-black font-medium h-260 px-20 py-15 mt-32 border-1 border-solid border-#999 lg:border-#D8D8D8 rounded-6 lg:j-h-150 lg:j-p-16 lg:j-mt-32 lg:j-text-14 lg:j-leading-22 lg:j-border-1 lg:j-rounded-5 xl:a-h-150 xl:a-p-16 xl:a-mt-32 xl:a-text-14 xl:a-leading-22 xl:a-border-1 xl:a-rounded-5 overflow-y-auto">
          ${this.configData.emailContent}
        </div>

        <button data-old-invite-new-email-mb-btn class="flex-center lg:hidden appearance-none max-w-full h-80 min-w-326 rounded-40 text-white bg-primary font-semibold mt-32">
          <span class="line-clamp-1">${this.configData.emailButtonDesc}</span>
        </button>

        <div class="w-full lg:text-black font-normal text-#666 text-26 leading-38 mt-32 lg:j-mt-16 lg:j-text-14 lg:j-leading-22 xl:a-mt-16 xl:a-text-14 xl:a-leading-22">
          ${this.configData.emailRemark}
        </div>
      `
    }
    handleEmailClick(emailPlaceholder) {
      const popupHtml = this.renderEmailPopup(emailPlaceholder)
      ZModle.getInstance(popupHtml, {
        id: `old-invite-new-rank-email-popup`,
        class: "old-invite-new-rank-email-popup-wrap",
        cb: (modal) => {
          const formDOM = modal.querySelector('form')
          const inputDOM = formDOM.querySelector('input')
          const buttonDOM = formDOM.querySelector('button')
          const mbButtonDOM = modal.querySelector('[data-old-invite-new-email-mb-btn]')
          const emailErrorTip = modal.querySelector('[data-email-popup-error-tip]')

          const { emailFormatErrorText, emailMessageSent, } = this.dataset

          const submit = async (e) => {
            e.preventDefault()

            buttonDOM.classList.add('btn--loading')
            mbButtonDOM.classList.add('btn--loading')
            const newerEmail = inputDOM.value
            if (!newerEmail.trim()) {
              emailErrorTip.innerText = emailPlaceholder
              emailErrorTip.classList.remove('hidden')

              buttonDOM.classList.remove('btn--loading')
              mbButtonDOM.classList.remove('btn--loading')
              return false
            }
            if (!/^\w+([-+.]\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*$/.test(newerEmail)) {
              emailErrorTip.innerText = emailFormatErrorText
              emailErrorTip.classList.remove('hidden')

              buttonDOM.classList.remove('btn--loading')
              mbButtonDOM.classList.remove('btn--loading')
              return false
            }

            try {
              // 生成 邀请链接
              const { data, message, } = await sendInviteEmail({ olderEmail: this.olderEmail, newerEmail, })

              if (data) {
                pushSuccessMessage(emailMessageSent)
              } else {
                pushErrorMessage(message)
              }
            } catch (err) {
              pushErrorMessage(err.message)
            } finally {
              buttonDOM.classList.remove('btn--loading')
              mbButtonDOM.classList.remove('btn--loading')
              inputDOM.value = ''
            }
          }

          // input change
          inputDOM.addEventListener('input', (e) => emailErrorTip.classList.add('hidden'))
          formDOM.addEventListener('submit', (e) => submit(e))
          mbButtonDOM.addEventListener('click', (e) => submit(e))
        }
      })
    }

    // 各社交平台分享插件调用
    getSocialShareAPI(pageShareUrl, type, content) {
      let url = '';
      switch (type) {
        case 'facebook':
          url = 'https://www.facebook.com/sharer.php?u=' + encodeURIComponent(pageShareUrl);
          break;
        case 'twitter':
          url = `https://twitter.com/intent/tweet?original_referer=${encodeURIComponent(pageShareUrl)}&ref_src=${encodeURIComponent('twsrc^tfw|twcamp^buttonembed|twterm^share|twgr^')}&text=${encodeURIComponent(content)}&url=${encodeURIComponent(`${pageShareUrl}`)}`;
          break;
        case 'whatsapp':
          url = `https://api.whatsapp.com/send?text=${content} ${encodeURIComponent(pageShareUrl)}`;
          break;
        case 'line':
          url = `http://line.me/R/msg/text/?${encodeURIComponent(content)} ${pageShareUrl}`
          break;
        case 'telegram':
          url = `https://t.me/share/url?url=${encodeURIComponent(`${pageShareUrl}`)}&text=${content}`;
          break;
        default:
          url = '';
          break;
      }
      return url;
    }

    // 初始化排行榜
    async initRank() {
      const headerData = this.renderRankHeader()
      if (headerData) {
        this.rankHeader.classList.remove('!hidden')
        this.rankHeader.innerHTML = headerData
      } else {
        this.rankHeader.classList.add('!hidden')
      }
      
      try {
        const { data } = await getOldInviteNewRank()

        if (data?.length > 0 && this.rankHeaderParamsArray.length > 0) {
          // 渲染排行榜数据
          this.rankUl.innerHTML = this.renderRankUl(data)

          // 初始化 无缝循环滚动
          new SeamlessScrolling({ container: this.rankUl, delay: 1000, }).observe()
        } else {
          this.rankUl.innerHTML = this.renderRankNodata(this.rankUl.dataset.rankNoDataText)
        }
      } catch (err) {
        this.rankUl.innerHTML = this.renderRankNodata(this.rankUl.dataset.rankNoDataText)
      }
    }
    // 获取邮箱排行榜名次
    async getEmailRank(email) {
      try {
        const { data } = await getOldInviteNewEmailRank({ email })
        if (data) {
          this.rankSelfData.innerHTML = this.renderRankSelfData(email, data)
          this.rankSelfData.classList.remove('!hidden')
        } else {
          this.rankSelfData.classList.add('!hidden')
        }
      } catch (err) {
        this.rankSelfData.classList.add('!hidden')
      }
    }
    // 渲染排行榜 table header
    renderRankHeader() {
      const rankHeaderLength = this.rankHeaderParamsArray.length
      let html = ''
      this.rankHeaderParamsArray.forEach((item, index) => {
        if (index === 0) {
          html += `<span class="block text-center ${rankHeaderLength===1?'!w-full':rankHeaderLength===2?'!w-1/2':'w-170'} lg:j-w-140 xl:a-w-140">${item}</span>`;
        } else if (index === 1) {
          html += `<span class="block text-center ${rankHeaderLength===2?'!w-1/2':'w-150'} lg:j-w-144 lg:j-ml-16 lg:j-mr-45 xl:a-w-144 xl:a-ml-16 xl:a-mr-45">${item}</span>`;
        } else {
          html += `<span class="block text-center flex-1">${item}</span>`;
        }
      })
      return html
    }
    // 渲染排行榜个人数据
    renderRankSelfData(email, data) {
      const rankHeaderLength = this.rankHeaderParamsArray.length
      let html = 
        data.rankNo == 1
          ?  `<span class="block text-center ${rankHeaderLength===1?'!w-full':rankHeaderLength===2?'!w-1/2':'w-170'} lg:j-w-140 xl:a-w-140">${this.renderFirstIcon()}</span>`
          : data.rankNo == 2
            ? `<span class="block text-center ${rankHeaderLength===1?'!w-full':rankHeaderLength===2?'!w-1/2':'w-170'} lg:j-w-140 xl:a-w-140">${this.renderSecondIcon()}</span>`
            : data.rankNo == 3
              ? `<span class="block text-center ${rankHeaderLength===1?'!w-full':rankHeaderLength===2?'!w-1/2':'w-170'} lg:j-w-140 xl:a-w-140">${this.renderThirdIcon()}</span>`
              : `<span class="block text-center ${rankHeaderLength===1?'!w-full':rankHeaderLength===2?'!w-1/2':'w-170'} lg:j-w-140 xl:a-w-140">${data.rankNo || '-'}</span>`
      if (rankHeaderLength >= 2) {
        html += `<span class="block text-center ${rankHeaderLength===2?'!w-1/2':'w-150'} line-clamp-1 lg:j-w-144 lg:j-ml-16 lg:j-mr-45 xl:a-w-144 xl:a-ml-16 xl:a-mr-45" ${email ? `title="${this.getEmailName(email)}"` : ''}>${this.getEmailName(email) || '-'}</span>`
      }
      if (rankHeaderLength >= 3) {
        html += `<span class="block text-center flex-1">${data.total}</span>`
      }
      return html
    }
    // 渲染排行榜 ul
    renderRankUl(data) {
      const rankHeaderLength = this.rankHeaderParamsArray.length
      let html = ''
      data.forEach((item, index) => {
        html += `
          <li class="flex items-center border-0 border-solid border-#EEE h-80 px-16 !border-b-[1px] lg:j-h-44 lg:j-h-44 lg:j-px-24 xl:a-h-44 xl:a-px-24">
            ${
              index === 0
                ?  `<span class="block text-center ${rankHeaderLength===1?'!w-full':rankHeaderLength===2?'!w-1/2':'w-170'} lg:j-w-140 xl:a-w-140">${this.renderFirstIcon()}</span>`
                : index === 1
                  ? `<span class="block text-center ${rankHeaderLength===1?'!w-full':rankHeaderLength===2?'!w-1/2':'w-170'} lg:j-w-140 xl:a-w-140">${this.renderSecondIcon()}</span>`
                  : index === 2
                    ? `<span class="block text-center ${rankHeaderLength===1?'!w-full':rankHeaderLength===2?'!w-1/2':'w-170'} lg:j-w-140 xl:a-w-140">${this.renderThirdIcon()}</span>`
                    : `<span class="block text-center ${rankHeaderLength===1?'!w-full':rankHeaderLength===2?'!w-1/2':'w-170'} lg:j-w-140 xl:a-w-140">${index + 1}</span>`
            }
            ${
              rankHeaderLength >= 2
                ? `<span class="block text-center ${rankHeaderLength===2?'!w-1/2':'w-150'} line-clamp-1 lg:j-w-144 lg:j-ml-16 lg:j-mr-45 xl:a-w-144 xl:a-ml-16 xl:a-mr-45" ${item.email ? `title="${this.getEmailName(item.email)}"` : ''}>${this.getEmailName(item.email) || '-'}</span>`
                : ''
            }
            ${
              rankHeaderLength >= 3
                ? `<span class="block text-center flex-1">${item.total}</span>`
                : ''
            }
          </li>
        `
      })
      return html
    }
    getEmailName(email) {
      const match = email.match(/^([^@]+)/)
      return match ? match[1] : null
    }
    renderRankNodata(noDataText) {
      return `<div class="w-full h-full flex-center">${noDataText}</div>`
    }
    renderFirstIcon() {
      return `
        <img class="w-64 h-64 lg:j-w-36 lg:j-h-36 xl:a-w-36 xl:a-h-36 object-contain" src="data:image/png;base64," alt="first icon" />
      `
    }
    renderSecondIcon() {
      return `
        <img class="w-64 h-64 lg:j-w-36 lg:j-h-36 xl:a-w-36 xl:a-h-36 object-contain" src="data:image/png;base64," alt="second icon" />
      `
    }
    renderThirdIcon() {
      return `
        <img class="w-64 h-64 lg:j-w-36 lg:j-h-36 xl:a-w-36 xl:a-h-36 object-contain" src="data:image/png;base64," alt="third icon" />
      `
    }
  })
}
